class Solution {
public:
    string destCity(vector<vector<string>>& paths) {
        set<string> leaves;
        for (auto& p : paths) leaves.insert(p[0]);
        for (int i = 0; i < (int)paths.size(); i++) {
            if (!leaves.count(paths[i][1])) return paths[i][1];
        }
        return "";
    }
};
